<template>
  <section class="proposal-workspace" :class="{ expanded }" aria-label="工作流候选工作区">
    <header class="workspace-header"><div><span class="eyebrow">WORKFLOW WORKSPACE</span><h2>{{ proposal?.name || candidate?.name || '工作流候选' }}</h2></div><button class="action-btn" :aria-label="expanded ? '收起工作区' : '展开工作区'" @click="expanded = !expanded">{{ expanded ? '收起' : '全屏' }}</button><button class="action-btn" aria-label="关闭工作区" @click="$emit('close')">关闭</button></header>
    <template v-if="proposal">
      <div class="proposal-summary"><span class="proposal-kind">{{ actionNames[proposal.action] }}</span><span class="version">v{{ proposal.version }}</span><span class="status-label">{{ statusLabel }}</span></div>
      <div class="workspace-tabs" role="tablist"><button v-for="tab in tabs" :id="`workspace-tab-${tab.id}`" :key="tab.id" role="tab" :aria-selected="activeTab === tab.id" :aria-controls="`workspace-panel-${tab.id}`" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">{{ tab.label }}</button></div>
      <div :id="`workspace-panel-${activeTab}`" class="workspace-body" role="tabpanel" :aria-labelledby="`workspace-tab-${activeTab}`">
        <div v-if="activeTab === 'overview'" class="overview">
          <p class="candidate-description">{{ candidate?.description || '请核对调度时间、节点和代码，再确认提交。' }}</p>
          <dl class="overview-grid"><div><dt>工作流 ID</dt><dd>{{ proposal.job_id || candidate?.job_id || '确认后生成' }}</dd></div><div><dt>调度触发器</dt><dd>{{ candidate?.trigger?.type || '未设置' }}</dd></div><div><dt>执行器</dt><dd>{{ candidate?.executor_alias || 'default' }}</dd></div><div><dt>存储器</dt><dd>{{ candidate?.jobstore_alias || 'default' }}</dd></div><div><dt>节点 / 依赖</dt><dd>{{ candidate?.workflow?.nodes?.length || 0 }} / {{ candidate?.workflow?.edges?.length || 0 }}</dd></div><div><dt>{{ proposal.action === 'run' ? '本次执行超时' : '工作流超时' }}</dt><dd>{{ effectiveTimeout === null ? '未设置' : `${effectiveTimeout} s` }}<small v-if="proposal.action === 'run' && timeoutReview.inherited && effectiveTimeout !== null">（沿用工作流配置）</small></dd></div></dl>
          <p v-if="proposal.action === 'run'" class="run-mode">执行方式：立即手动执行一次。</p><div class="config-section"><h3>调度参数</h3><pre>{{ pretty(candidate?.trigger?.args || {}) }}</pre></div>
          <div v-if="proposal.action === 'create' && ['pending', 'awaiting_confirmation'].includes(proposal.status)" class="enable-option"><el-switch :model-value="enabled" :disabled="busy" @change="changeEnabled"/><div><strong>{{ enabled ? '确认后启用调度' : '仅保存，暂不调度' }}</strong><p>启用状态修改会生成新的候选版本。</p></div></div>
          <div class="task-inventory"><h3>任务节点</h3><button v-for="node in candidate?.workflow?.nodes || []" :key="node.node_id" class="task-row" @click="selectedNode = node.node_id; activeTab = 'code'"><span class="task-icon">{{ node.task?.type === 'bash' ? '$' : 'Py' }}</span><span><strong>{{ node.name || node.node_id }}</strong><small>{{ node.node_id }} · {{ node.task?.type }}</small></span><span class="task-arrow">↗</span></button></div>
        </div>
        <div v-else-if="activeTab === 'dag'" class="dag-panel"><WorkflowEditor v-if="dag?.nodes.length" :key="`${proposal.proposal_id}-${proposal.version}`" ref="editor" readonly @node-click="onNodeClick"/><p v-else class="empty-panel">候选没有 DAG 节点</p><div v-if="selectedRawNode" class="node-inspector"><strong>{{ selectedRawNode.name || selectedRawNode.node_id }}</strong><pre>{{ pretty(selectedRawNode) }}</pre></div></div>
        <div v-else-if="activeTab === 'code'" class="code-panel"><div class="node-picker"><button v-for="node in candidate?.workflow?.nodes || []" :key="node.node_id" :class="{ active: selectedNode === node.node_id }" @click="selectedNode = node.node_id">{{ node.name || node.node_id }}</button></div><template v-if="selectedRawNode"><div class="code-heading"><strong>{{ selectedRawNode.task?.type }}</strong><button class="action-btn" @click="copyCode">{{ copied ? '已复制' : '复制代码' }}</button><span>重试 {{ selectedRawNode.retries || 0 }} 次 · 超时 {{ selectedRawNode.timeout ?? selectedRawNode.task?.timeout ?? '未设置' }}</span></div><pre class="source-code">{{ sourceCode(selectedRawNode.task) }}</pre><h3>完整节点配置</h3><pre>{{ pretty(selectedRawNode) }}</pre></template><p v-else class="empty-panel">选择任务节点查看代码</p><details><summary>完整候选配置</summary><pre>{{ pretty(candidate) }}</pre></details></div>
        <div v-else class="diff-panel"><p class="field-hint">{{ proposal.action === 'create' ? '创建新工作流，以下是新增配置。' : '对比提交前后的原始配置。' }}</p><article v-for="(change, index) in proposal.diff || []" :key="index" class="diff-change"><h3>{{ change.path || '/' }}</h3><div class="diff-columns"><pre class="before"><span>变更前</span>{{ pretty(change.before) }}</pre><pre class="after"><span>变更后</span>{{ pretty(change.after) }}</pre></div></article><p v-if="!proposal.diff?.length" class="empty-panel">无配置差异</p><details v-if="proposal.before"><summary>原始配置</summary><pre>{{ pretty(proposal.before) }}</pre></details></div>
      </div>
      <footer class="proposal-footer"><p v-if="proposal.expires_at">候选有效期至 {{ formatDate(proposal.expires_at) }}</p><p v-if="!approvable && ['pending', 'awaiting_confirmation'].includes(proposal.status)" class="expiry-warning">候选已过期，请重新生成。</p><p v-if="confirmationUnavailable && ['pending', 'awaiting_confirmation'].includes(proposal.status)" class="expiry-warning" role="status">{{ confirmationUnavailable }}</p><OperationCard v-if="proposal.operation_id" :operation-id="proposal.operation_id"/><div v-if="['pending', 'awaiting_confirmation'].includes(proposal.status)" class="confirmation-actions"><button class="action-btn" :disabled="busy" @click="store.reject(proposal.proposal_id)">放弃候选</button><button class="btn-primary" :disabled="busy || !approvable || !!confirmationUnavailable" @click="store.approve(proposal.proposal_id)">{{ busy ? '正在处理…' : confirmText }}</button></div><p v-else class="field-hint">{{ statusLabel }}。此候选不可重复提交。</p></footer>
    </template>
    <p v-else class="empty-panel">正在读取候选配置…</p>
  </section>
</template>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { jobFromApi } from '@/api/mappers'
import { canApprove } from '@/agent/protocol'
import { runTimeoutView } from '@/agent/proposalReview'
import { useAgentStore } from '@/stores/agent'
import WorkflowEditor from '@/views/jobs/WorkflowEditor.vue'
import OperationCard from './OperationCard.vue'
const props = defineProps<{ proposalId: string }>(); defineEmits<{ close: [] }>()
const store = useAgentStore(); const expanded = ref(false); const activeTab = ref('overview'); const selectedNode = ref(''); const editor = ref<InstanceType<typeof WorkflowEditor> | null>(null); const now = ref(new Date())
const copied = ref(false); let copyTimer: ReturnType<typeof setTimeout> | null = null
async function copyCode() { if (!selectedRawNode.value) return; try { await navigator.clipboard.writeText(sourceCode(selectedRawNode.value.task)); copied.value = true; if (copyTimer) clearTimeout(copyTimer); copyTimer = setTimeout(() => { copied.value = false }, 1800) } catch { store.error = '无法复制代码，请检查浏览器剪贴板权限。' } }
const tabs = [{ id: 'overview', label: '概览' }, { id: 'dag', label: 'DAG' }, { id: 'code', label: '代码' }, { id: 'diff', label: '变更' }]
const actionNames: Record<string, string> = { create: '创建工作流', update: '更新工作流', run: '立即执行' }
const proposal = computed(() => store.proposals[props.proposalId])
const candidate = computed(() => proposal.value?.after || proposal.value?.payload || proposal.value?.before)
const timeoutReview = computed(() => runTimeoutView(proposal.value || {}))
const effectiveTimeout = computed(() => proposal.value?.action === 'run' ? timeoutReview.value.seconds : typeof candidate.value?.workflow_timeout === 'number' ? candidate.value.workflow_timeout : null)
const dag = computed(() => { const mapped = candidate.value ? jobFromApi(candidate.value).dag : null; return mapped ? { ...mapped, nodes: mapped.nodes.map(node => ({ ...node, task_node: { ...node.task_node, name: node.task_node.name || node.node_id } })) } : null })
const selectedRawNode = computed(() => candidate.value?.workflow?.nodes?.find(node => node.node_id === selectedNode.value))
const busy = computed(() => !!store.pendingActions[props.proposalId])
const enabled = computed(() => candidate.value?.enabled !== false && candidate.value?.status !== 'paused' && proposal.value?.payload?.enabled !== false)
const approvable = computed(() => !!proposal.value && canApprove(proposal.value, proposal.value.version, now.value))
const confirmationUnavailable = computed(() => store.configPending ? '正在更新 Agent 启用状态，请稍候再确认。' : !store.config?.configured ? '模型服务尚未配置，请前往 Agent 设置完成配置后再确认。' : !store.config.enabled ? 'Agent 已停用，请先打开 Agent 开关再确认候选。' : '')
const statusLabel = computed(() => ({ pending: '待确认', awaiting_confirmation: '待确认', committing: '正在提交', approved: '已确认', rejected: '已放弃', expired: '已过期', stale: '版本已变化', superseded: '已被新候选替代', committed: '已提交' } as Record<string, string>)[proposal.value?.status || ''] || proposal.value?.status)
const confirmText = computed(() => proposal.value?.action === 'create' ? (enabled.value ? '确认创建并启用' : '确认保存') : proposal.value?.action === 'update' ? '确认更新' : '确认立即执行')
const pretty = (value: unknown) => value === undefined ? '—' : JSON.stringify(value, null, 2)
const formatDate = (value: string) => new Date(value).toLocaleString()
function sourceCode(task: Record<string, unknown>) { return String(task.script || task.command || task.script_path || task.ref || '') }
function onNodeClick(nodeId: string) { selectedNode.value = nodeId }
function changeEnabled(value: string | number | boolean) { if (proposal.value) void store.revise(proposal.value.proposal_id, !!value) }
watch([() => props.proposalId, () => proposal.value?.version], () => { selectedNode.value = candidate.value?.workflow?.nodes?.[0]?.node_id || '' }, { immediate: true })
watch([activeTab, dag, editor, expanded], async () => { await nextTick(); if (activeTab.value === 'dag' && dag.value && editor.value) editor.value.loadDag(dag.value) }, { flush: 'post' })
let timer: ReturnType<typeof setInterval>
onMounted(() => { if (!proposal.value) void store.loadProposal(props.proposalId); timer = setInterval(() => { now.value = new Date() }, 10000) })
onBeforeUnmount(() => { clearInterval(timer); if (copyTimer) clearTimeout(copyTimer) })
</script>
<style scoped>
.proposal-workspace { display: flex; flex-direction: column; min-height: 0; height: 100%; background: var(--bg-base); border: 1px solid var(--border-default); border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-sm); }.proposal-workspace.expanded { position: fixed; inset: 18px; z-index: 2000; box-shadow: var(--shadow-lg); }
.workspace-header { display: flex; align-items: center; gap: 8px; padding: 20px 20px 12px; }.workspace-header > div { flex: 1; min-width: 0; }.eyebrow { font-size: 10px; font-weight: 700; letter-spacing: .12em; color: var(--text-muted); }.workspace-header h2 { font-size: 18px; margin-top: 4px; overflow-wrap: anywhere; }
.proposal-summary { display: flex; align-items: center; gap: 10px; padding: 0 20px 16px; font-size: 12px; }.proposal-kind { background: var(--color-primary-soft); color: var(--color-primary-text); padding: 3px 8px; border-radius: var(--radius-sm); }.version { color: var(--text-muted); }.status-label { margin-left: auto; color: var(--color-warning); }
.workspace-tabs { display: flex; border-block: 1px solid var(--border-subtle); padding: 0 12px; }.workspace-tabs button { background: none; border: 0; border-bottom: 2px solid transparent; color: var(--text-muted); padding: 13px 16px; font: inherit; cursor: pointer; }.workspace-tabs button.active { color: var(--color-primary-text); border-bottom-color: var(--color-primary); }.workspace-body { flex: 1; overflow: auto; padding: 20px; min-height: 240px; } .candidate-description { font-size: 13px; color: var(--text-secondary); line-height: 1.8; margin-bottom: 20px; white-space: pre-wrap; }
.overview-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px 12px; }.overview-grid dt { color: var(--text-muted); font-size: 11px; margin-bottom: 5px; }.run-mode { margin-top: 18px; color: var(--color-primary-text); font-size: 12px; }.overview-grid dd small { display: block; color: var(--text-muted); font-size: 10px; margin-top: 4px; }.overview-grid dd { font-size: 13px; overflow-wrap: anywhere; }h3 { font-size: 12px; color: var(--text-secondary); margin: 20px 0 8px; }pre { background: var(--code-bg); color: var(--code-text); padding: 14px; border-radius: var(--radius-sm); overflow: auto; font-size: 12px; line-height: 1.7; white-space: pre-wrap; overflow-wrap: anywhere; }
.enable-option { display: flex; align-items: center; gap: 12px; background: var(--color-primary-soft); padding: 12px; margin: 20px 0; border-radius: var(--radius-md); }.enable-option strong { font-size: 13px; }.enable-option p { font-size: 11px; color: var(--text-muted); margin-top: 3px; }.task-row { width: 100%; display: flex; align-items: center; gap: 10px; padding: 12px 0; background: none; border: none; border-bottom: 1px solid var(--border-subtle); color: var(--text-primary); cursor: pointer; text-align: left; }.task-icon { width: 32px; height: 32px; border: 1px solid var(--border-default); background: var(--bg-surface); border-radius: 8px; display: grid; place-items: center; font-family: monospace; color: var(--color-primary-text); }.task-row strong { display: block; font-size: 12px; }.task-row small { display: block; color: var(--text-muted); font-size: 11px; margin-top: 4px; }.task-arrow { margin-left: auto; color: var(--text-muted); }
.dag-panel { height: 100%; min-height: 420px; display: flex; flex-direction: column; }.dag-panel > :first-child { min-height: 380px; flex: 1; }.node-inspector { max-height: 220px; overflow: auto; border-top: 1px solid var(--border-subtle); padding: 12px; font-size: 12px; }.node-inspector pre { margin-top: 6px; }.node-picker { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 16px; }.node-picker button { padding: 6px 10px; border: 1px solid var(--border-default); background: var(--bg-surface); border-radius: var(--radius-sm); color: var(--text-secondary); cursor: pointer; }.node-picker button.active { background: var(--color-primary-soft); border-color: var(--color-primary); color: var(--color-primary-text); }.code-heading { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; font-size: 11px; margin-bottom: 8px; color: var(--text-muted); }.source-code { min-height: 180px; }.diff-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }.diff-columns pre span { display: block; margin-bottom: 8px; color: var(--text-muted); font-family: var(--font-body); }.diff-columns .before { border: 1px solid var(--color-danger-soft); color: var(--color-danger); }.diff-columns .after { border: 1px solid var(--color-success-soft); color: var(--color-success); }
.proposal-footer { padding: 14px 20px 20px; border-top: 1px solid var(--border-subtle); background: var(--bg-base); max-height: 280px; overflow: auto; }.proposal-footer > p { font-size: 11px; color: var(--text-muted); margin-bottom: 10px; }.proposal-footer .expiry-warning { color: var(--color-warning); }.confirmation-actions { display: flex; justify-content: flex-end; gap: 8px; }.empty-panel { text-align: center; color: var(--text-muted); padding: 50px 16px; font-size: 13px; }summary { cursor: pointer; margin-top: 20px; color: var(--text-muted); font-size: 12px; }details pre { margin-top: 8px; }
@media (max-width: 600px) { .workspace-header { padding: 16px 12px 12px; }.workspace-header h2 { font-size: 16px; }.workspace-tabs button { flex: 1; padding-inline: 6px; }.workspace-body { padding: 14px; }.proposal-footer { padding: 14px; }.diff-columns { grid-template-columns: 1fr; }.proposal-workspace.expanded { inset: 6px; }.confirmation-actions button { flex: 1; } }
</style>
